/**
 * Determines whether an automatic row limit should be appended to a SQL query.
 *
 * An auto limit is only appended to simple, single SELECT statements that don't
 * already define their own limit. We intentionally bail out on comments and
 * multiple statements since appending a limit in those cases could produce an
 * invalid or unexpected query.
 */
export function checkIfAppendLimitRequired(sql: string, limit: number = 0) {
  // Normalise the query by trimming whitespace and removing any trailing
  // semicolons so that a single terminated statement isn't treated as multiple.
  const cleanedSql = sql.trim().replace(/[;\s]*$/, '')

  const isSelectStatement = /^select\b/i.test(cleanedSql)
  const containsLimitKeyword = /\blimit\b/i.test(cleanedSql)
  const containsLineComments = cleanedSql.includes('--')
  const containsMultipleStatements = cleanedSql.includes(';')

  const appendAutoLimit =
    limit > 0 &&
    isSelectStatement &&
    !containsLimitKeyword &&
    !containsLineComments &&
    !containsMultipleStatements

  return { appendAutoLimit }
}

/**
 * Appends a row limit to a SQL query, ensuring the resulting string is
 * terminated by exactly one semicolon.
 */
export function suffixWithLimit(sql: string, limit: number) {
  const cleanedSql = sql.replace(/[;\s]*$/, '')
  return `${cleanedSql} limit ${limit};`
